#include <string.h>#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr putOverheadTexture ( Str255 theNewFileName );OSErr putOverheadTexture ( Str255 thePlugFileName ){//----------------------------------vars--------------------------------------------------	short			thePlugFileRef;	OSErr			theError;	FSSpec			thePlugFSSpec;	char			*theTexture;	short			theTempWidth, theTempHeight;	long			theWidth, theHeight, theSize;	long			theOffset;		const long		kPaletteOffset		= 384L;	const long		kTheWidthOffset		= 2876L;	const long		kTheHeightOffset	= 2878L;	const long		kTheBitsOffset		= 2928L;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// new plug file	theError = FSMakeFSSpec (0L, 0L, thePlugFileName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	FileSeek ( thePlugFileRef, kTheWidthOffset );	FileRead ( &theTempWidth, 2L, thePlugFileRef );	FileSeek ( thePlugFileRef, kTheHeightOffset );	FileRead ( &theTempHeight, 2L, thePlugFileRef );		theWidth = (long) theTempWidth;	theHeight = (long) theTempHeight;	theSize = theWidth * theHeight;	theOffset = 2976 + 4 * theHeight;	FileSeek ( thePlugFileRef, 384L );	FileRead ( &thePalette, 2080L, thePlugFileRef );		theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	theError = readBMP ( "\p:Graphics.in:overhead.bmp", theWidth, theHeight, &thePalette, theTexture );	if ( theError != noErr ){		DisposePtr ( (Ptr) theTexture );		FSClose ( thePlugFileRef );		return theError;	}	FileSeek ( thePlugFileRef, 384L );	FileWrite ( &thePalette, 2080L, thePlugFileRef );	FileSeek ( thePlugFileRef, theOffset );	FileWrite (theTexture, theSize, thePlugFileRef );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return	noErr;}